INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41911, 'Zechariah 6:9', 'Zechariah', 6, 9, 'بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_9.mp3', '', 1761754199, 1761754199),
(41912, 'Zechariah 6:10', 'Zechariah', 6, 10, '”د جلاوطن کړے شوى خلدى، طوبياه او يدعياه نه سپين زر او سرۀ زر واخله، څوک چې د بابل نه راغلى دى. هم په هغه ورځ د يوسياه د صفنياه د زوئ کور ته لاړ شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_10.mp3', '', 1761754199, 1761754199),
(41913, 'Zechariah 6:11', 'Zechariah', 6, 11, 'د هغوئ د سپينو زرو او سرو زرو تحفه واخله او تاج ترې جوړ کړه، او دا د مشر اِمام د يهوصدق د زوئ يشوَع په سر کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_11.mp3', '', 1761754199, 1761754199),
(41914, 'Zechariah 6:12', 'Zechariah', 6, 12, 'هغۀ ته ووايه چې، مالِک خُدائ ربُ الافواج دا فرمائى، ”دا هغه سړے دے د چا نوم چې څانګه ده، او دے به د خپل ځان نه څانګې خورې کړى او د مالِک خُدائ کور به جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_12.mp3', '', 1761754199, 1761754199),
(41915, 'Zechariah 6:13', 'Zechariah', 6, 13, 'دا هغه څوک دے چې د مالِک خُدائ کور به جوړ کړى او دۀ ته به د بادشاهۍ جامې ورواغوستے شى او په تخت به کښېنى او بادشاهى به کوى. او په خوا کښې به اِمام د دۀ تخت سره ولاړ وى. او د دواړو په مينځ کښې به جوړ توړ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_13.mp3', '', 1761754199, 1761754199),
(41916, 'Zechariah 6:14', 'Zechariah', 6, 14, 'د خلدى، طوبياه، يدعياه او حين د صفنياه زوئ ته به تاج د مالِک خُدائ په کور کښې د يادګار په توګه ورکړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_14.mp3', '', 1761754199, 1761754199),
(41917, 'Zechariah 6:15', 'Zechariah', 6, 15, 'هغه څوک چې لرې دى هغوئ به راشى او د مالِک خُدائ د کور په جوړولو کښې به مدد وکړى. او تاسو ته به پته ولګى چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم. دا به وشى خو چې تاسو د مالِک خُدائ د خپل خُدائ پاک پوره تابعدارى وکړئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_15.mp3', '', 1761754199, 1761754199),
(41918, 'Psalms 63:1', 'Psalms', 63, 1, 'ای خدایه ته زما خدای یې زه رجوع کومه تاته خدایه زه په خپل زړه کې ستا لېوال یمه لکه د وچې او بېکاره للمې ځمکې په شان زما روح تږی دی د ستا دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_1.mp3', '', 1761754199, 1761754199),
(41919, 'Psalms 63:2', 'Psalms', 63, 2, 'ما یې لیدلی په سپېڅلي ځای کې د ستا قدرت او ستا جلال مې په ځیر ځیر کتلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_2.mp3', '', 1761754199, 1761754199),
(41920, 'Psalms 63:3', 'Psalms', 63, 3, 'دا ستا مینه تلپاتې ده بهتره له ژوندونه نو زما شونډې به تا ستایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_3.mp3', '', 1761754199, 1761754199),
(41921, 'Psalms 63:4', 'Psalms', 63, 4, 'ترڅو ژوندی یم ستا ثنا به وایم پورته کوم به خپل لاسونه په دعا کې زه د ستا په نامه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_4.mp3', '', 1761754199, 1761754199),
(41922, 'Psalms 63:5', 'Psalms', 63, 5, 'داسې به موړ شم لکه څوک چې په مېله کې غوړ خوراک وکړي په خوشحالۍ سره به وایم ستا ثنا او صفت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_5.mp3', '', 1761754199, 1761754199),
(41923, 'Psalms 63:6', 'Psalms', 63, 6, 'کله زه پروت چې په بستر کې یمه تا یادوم ټوله شپه ستا په اړه فکر کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_6.mp3', '', 1761754199, 1761754199),
(41924, 'Psalms 63:7', 'Psalms', 63, 7, 'ځکه چې ته مې مددګار وې همېش د سیوري لاندې د وزرونو د ستا د خوشحالۍ سندرې وایمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_7.mp3', '', 1761754199, 1761754199),
(41925, 'Psalms 63:8', 'Psalms', 63, 8, 'ما خپل روح تا پورې تړلی دی ستا ځواکمن لاس کوي ملاتړ زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_8.mp3', '', 1761754199, 1761754199),
(41926, 'Psalms 63:9', 'Psalms', 63, 9, 'خو څوک چې هڅه کړي چې ما ووژني هغوی به لاړ شي د مړو دنیا ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_9.mp3', '', 1761754199, 1761754199),
(41927, 'Psalms 63:10', 'Psalms', 63, 10, 'په جنګ کې مړه به شي په تورو هغوی شي به یې مړي د سورلنډیانو خوراک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_10.mp3', '', 1761754199, 1761754199),
(41928, 'Psalms 63:11', 'Psalms', 63, 11, 'خو پاچا به خوشحالي کوي د خدای په خاطر څوک چې قسم خوري د خدای په نوم د هغه ثنا او صفت به کوي خو د دروغجنو خولې به بندې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms63_verse_11.mp3', '', 1761754199, 1761754199),
(41929, 'Zephaniah 3:1', 'Zephaniah', 3, 1, 'افسوس د ظالمانو په ښار چې سرکشه او ناپاکه دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_1.mp3', '', 1761754199, 1761754199),
(41930, 'Zephaniah 3:2', 'Zephaniah', 3, 2, 'هغه د هيچا تابعدارى نۀ کوى، هغه تربيت نۀ قبلوى. هغه په مالِک خُدائ يقين نۀ کوى، هغه خپل خُدائ پاک ته نزدې نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_2.mp3', '', 1761754199, 1761754199),
(41931, 'Zephaniah 3:3', 'Zephaniah', 3, 3, 'د دې آفسران غړمبېدونکى زمرى دى، د دې حکمرانان د ماښام ليوانو په شان دى، څوک چې تر سحر پورې خپل ټول ښکار خورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_3.mp3', '', 1761754199, 1761754199),
(41932, 'Zephaniah 3:4', 'Zephaniah', 3, 4, 'د دې پېغمبران کبرژن دى، هغوئ غداران دى، د هغې اِمامان د مقدسو ځايونو بې‌حرمتى کوى او د شريعت نافرمانى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_4.mp3', '', 1761754199, 1761754199),
(41933, 'Zephaniah 3:5', 'Zephaniah', 3, 5, 'مالِک خُدائ په هغه ښار کښې دے هغه صادق دے، هغه هيڅ بې‌اِنصافى نۀ کوى. هغه هر سحر اِنصاف کوى او هره ورځ خپل اِنصاف قائم ساتى. خو بدعمله خلق هيڅ په شرم نۀ پوهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_5.mp3', '', 1761754199, 1761754199),
(41934, 'Zephaniah 3:6', 'Zephaniah', 3, 6, '”ما قومونه ختم کړل، د هغوئ قلعه ګانې مې تباه کړې، ما د هغوئ کوڅې ويجاړې کړې، په هغې کښې څوک تګ راتګ نۀ کوى. د هغوئ ښارونه خالى شوى دى، هيڅ څوک به په کښې پاتې نۀ شى، يو هم نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_6.mp3', '', 1761754199, 1761754199),
(41935, 'Zephaniah 3:7', 'Zephaniah', 3, 7, 'ما ښار ته ووئيل، يقيناً به تۀ زما نه وويرېږې او زما تربيت به قبول کړې. بيا به د هغۀ د اوسېدو ځائ تباه نۀ شى، لکه څنګه چې زما د هغۀ خلاف منصوبه وه. خو د هغوئ اوس هم دا شوق دے چې هغه ټولې بدعملۍ چې کومې يې مخکښې کولې وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_7.mp3', '', 1761754199, 1761754199),
(41936, 'Zephaniah 3:8', 'Zephaniah', 3, 8, 'مالِک خُدائ فرمائى چې، ”په دې وجه ما ته انتظار وکړئ، په کومه ورځ چې زۀ به ښکار ونيسم. ما فېصله کړې ده چې قومونه راغونډ کړم، بادشاهۍ رايوځائ کړم، او خپل قهر او سخته غصه پرې نازله کړم. زما د غېرتى قهر په اور به ټوله دُنيا وسوزى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_8.mp3', '', 1761754199, 1761754199),
(41937, 'Zephaniah 3:9', 'Zephaniah', 3, 9, 'بيا به زۀ د خلقو خبرې پاکې کړم، چې هغوئ ټول د مالِک خُدائ نوم واخلى او اوږه په اوږه د هغۀ خِدمت وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_9.mp3', '', 1761754199, 1761754199),
(41938, 'Zephaniah 3:10', 'Zephaniah', 3, 10, 'د ايتهوپيا د سيندونو بل طرف نه به زما عبادت کوونکى، زما خوارۀ وارۀ خلق، ما له نذرانې راوړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_10.mp3', '', 1761754199, 1761754199),
(41939, 'Zephaniah 3:11', 'Zephaniah', 3, 11, 'په هغه ورځ به تاسو د هغه ټولو خراب کارونو په وجه چې تاسو ما سره کړى دى ونۀ شرمېږئ، ځکه چې زۀ به د دې ښار نه هغه خلق لرې کړم چې په خپل غرور خوشحالۍ کوى. تۀ به بيا کله زما په مقدس غر غرور ونۀ کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_11.mp3', '', 1761754199, 1761754199),
(41940, 'Zephaniah 3:12', 'Zephaniah', 3, 12, 'خو زۀ به په تا کښې خاکساره او عاجز خويه خلق پرېږدم، څوک چې د مالِک خُدائ په نوم يقين کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_12.mp3', '', 1761754199, 1761754199),
(41941, 'Zephaniah 3:13', 'Zephaniah', 3, 13, 'د بنى اِسرائيلو ژوندى پاتې خلق به غلط کار نۀ کوى، هغوئ به دروغ نۀ وائى، او نۀ به د هغوئ په ژبه دوکه وى. هغوئ به خورى څښى او آرام به کوى او هيڅ څوک به هغوئ نۀ يروى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_13.mp3', '', 1761754199, 1761754199),
(41942, 'Zephaniah 3:14', 'Zephaniah', 3, 14, 'سندرې ووايه، اے د صيون لورې، په زوره چغې ووهه، اے بنى اِسرائيله. خوشحاله شه او په خپل پوره زړۀ سره خوشحالى وکړه، اے صيون لورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_14.mp3', '', 1761754199, 1761754199),
(41943, 'Zephaniah 3:15', 'Zephaniah', 3, 15, 'مالِک خُدائ ستاسو سزا ختمه کړې ده، هغۀ ستاسو دشمنان واپس کړل. مالِک خُدائ، د اِسرائيل بادشاه، ستاسو مل دے، تاسو به بيا هيڅکله د څۀ نقصان نه نۀ يرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_15.mp3', '', 1761754199, 1761754199),
(41944, 'Zephaniah 3:16', 'Zephaniah', 3, 16, 'په هغه ورځ به هغوئ يروشلم ته ووائى چې، ”يرېږه مه، اے صيونه، پرى نۀ ږدئ چې ستا لاسونه کمزورى پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_16.mp3', '', 1761754199, 1761754199),
(41945, 'Zephaniah 3:17', 'Zephaniah', 3, 17, 'مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے، هغه طاقتور دے او تاسو به بچ کړى. هغه به تاسو نه ډېر خوشحاله وى، هغه به تا په خپلې مينې خاموش کړى، هغه به په تا په سندرو سره خوشحالى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_17.mp3', '', 1761754199, 1761754199),
(41946, 'Zephaniah 3:18', 'Zephaniah', 3, 18, 'زۀ به هغوئ ستاسو نه لرې کړم څوک چې د مقرر شوى اخترونو په وجه غمژن وُو نو دا به نور ستاسو دپاره د شرم سبب نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_18.mp3', '', 1761754199, 1761754199),
(41947, 'Zephaniah 3:19', 'Zephaniah', 3, 19, 'په هغه وخت به زۀ معامله وکړم هغوئ ټولو سره چې په تا يې ظلم زياتے کړے دے، زۀ به ګوډيان بچ کړم او هغوئ به راغونډ کړم چې څوک خوارۀ وارۀ شوى دى. زۀ به هغوئ له عزت او جلال ورکړم، په هر مُلک کښې چرته چې دوئ رسوا شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_19.mp3', '', 1761754199, 1761754199),
(41948, 'Zephaniah 3:20', 'Zephaniah', 3, 20, 'په هغه وخت به زۀ تاسو راغونډ کړم، په هغه وخت به زۀ تاسو خپلو کورونو ته راولم. زۀ به تاسو ته د دُنيا په ټولو خلقو کښې عزت او جلال درکړم، زۀ به تاسو ستاسو د خپلو سترګو د وړاندې بيا آباد کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah3_verse_20.mp3', '', 1761754199, 1761754199),
(41949, 'Jeremiah 36:1', 'Jeremiah', 36, 1, 'په يهوداه کښې د يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال، مالِک خُدائ يرمياه ته پېغام ورکړو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_1.mp3', '', 1761754199, 1761754199),
(41950, 'Jeremiah 36:2', 'Jeremiah', 36, 2, '”يو طومار راواخله او په هغې زما ټول کلام کوم چې ما درته د يهوداه، د اِسرائيل او د ټولو قومونو په خلاف د يوسياه د بادشاهۍ د وخت نه تر اوسه پورې نازل کړے دے وليکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_2.mp3', '', 1761754199, 1761754199),
(41951, 'Jeremiah 36:3', 'Jeremiah', 36, 3, 'شايد چې د يهوداه خلق د هغه ټولو افتونو په حقله واورى کوم چې زما په هغوئ د راوستلو نيت دے، نو کۀ هر يو د خپلې بدعملۍ نه راوګرځى نو بيا به زۀ د هغوئ ګناهونه او بدعملونه معاف کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_3.mp3', '', 1761754199, 1761754199),
(41952, 'Jeremiah 36:4', 'Jeremiah', 36, 4, 'نو بيا يرمياه باروک د نيرياه زوئ راوغوښتلو، او کله چې يرمياه هغۀ ته هغه هر څۀ ووئيل کوم چې مالِک خُدائ هغۀ ته فرمائيلى وُو، نو باروک هغه په يو طومار کښې وليکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_4.mp3', '', 1761754199, 1761754199),
(41953, 'Jeremiah 36:5', 'Jeremiah', 36, 5, 'نو بيا يرمياه باروک ته وفرمائيل چې، ”زۀ دلته نظر بند يم نو د مالِک خُدائ کور ته دننه تلے نۀ شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_5.mp3', '', 1761754199, 1761754199),
(41954, 'Jeremiah 36:6', 'Jeremiah', 36, 6, 'نو بيا تاسو د مالِک خُدائ کور ته کله چې روژه وى لاړ شئ او خلقو ته هغه څۀ ولولئ کوم چې ما تاسو ته وفرمائيل او تاسو هغه په يو طومار کښې وليکل. دا د يهوداه ټولو هغه خلقو ته ولوله کوم چې د خپلو ښارونو نه د عبادت دپاره دلته راغلى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_6.mp3', '', 1761754199, 1761754199),
(41955, 'Jeremiah 36:7', 'Jeremiah', 36, 7, 'شايد چې هغوئ مالِک خُدائ ته عرض او مِنت زارى وکړى او ټول د خپلو بدو لارو نه راوګرځى، ځکه چې د مالِک خُدائ قهر او غضب ډېر لوئ دے کوم چې يې د دې خلقو خلاف اعلان کړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_7.mp3', '', 1761754199, 1761754199),
(41956, 'Jeremiah 36:8', 'Jeremiah', 36, 8, 'باروک د نيرياه زوئ هم هغه شان وکړل څنګه چې ورته يرمياه نبى حکم کړے وو، نو د هغه طومار نه يې د مالِک خُدائ کلام د مالِک خُدائ په کور کښې ولوستلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_8.mp3', '', 1761754199, 1761754199),
(41957, 'Jeremiah 36:9', 'Jeremiah', 36, 9, 'يهويقيم د يوسياه زوئ د يهوداه بادشاه د بادشاهۍ د پينځم کال په نهمه مياشت د يروشلم ټولو خلقو ته او د هغوئ دپاره څوک چې د يهوداه د ښارونو نه راغلى وُو، د روژې اعلان وکړو او هغوئ د مالِک خُدائ دپاره روژه ونيوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_9.mp3', '', 1761754199, 1761754199),
(41958, 'Jeremiah 36:10', 'Jeremiah', 36, 10, 'د مالِک خُدائ په کور کښې د ګمرياه د سافن زوئ منشى د کوټې نه، کومه چې د دربار په بره حِصه کښې وه او د مالِک خُدائ د کور د داخلېدو د نوې دروازې سره نزدې وه، باروک ټولو خلقو ته چې هلته موجود وُو د يرمياه کلام د طومار نه تلاوت کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_10.mp3', '', 1761754199, 1761754199),
(41959, 'Jeremiah 36:11', 'Jeremiah', 36, 11, 'کله چې ميکاياه د ګمرياه زوئ او د سافن نمسى د مالِک خُدائ کلام د طومار نه واورېدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_11.mp3', '', 1761754199, 1761754199),
(41960, 'Jeremiah 36:12', 'Jeremiah', 36, 12, 'نو هغه په شاهى محل کښې لاندې د منشى کوټې ته لاړو، چرته چې ټول آفسران ناست وُو. اليسمع، د دربار منشى، د سمعياه زوئ دلاياه، د عکبور زوئ الناتن، د سافن زوئ ګمرياه، د حننياه زوئ صدقياه او نور ټول آفسران هلته موجود وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_12.mp3', '', 1761754199, 1761754199),
(41961, 'Jeremiah 36:13', 'Jeremiah', 36, 13, 'نو ميکاياه هغوئ ته هغه هر څۀ ووئيل څۀ چې باروک خلقو ته د طومار نه بيانول او هغۀ ترې اورېدلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_13.mp3', '', 1761754199, 1761754199),
(41962, 'Jeremiah 36:14', 'Jeremiah', 36, 14, 'نو ټولو آفسرانو په مشورې سره يهودى د نتنياه زوئ، د شلمياه نمسى او د کوشى کړوسے باروک ته ورولېږلو چې ورته دا ووائى، ”آفسران وائى چې راشه، او ځان سره هغه طومار هم راوړه کوم چې تا ټولو خلقو ته ولوستلو.“ نو باروک د نيرياه زوئ د هغه طومار سره چې کوم يې په لاس کښې وو هغوئ له ورغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_14.mp3', '', 1761754199, 1761754199),
(41963, 'Jeremiah 36:15', 'Jeremiah', 36, 15, 'نو هغوئ هغۀ ته ووئيل چې، ”مهربانى وکړه دلته کښېنه او مونږ ته دا طومار ولوله.“ نو باروک ورته هغه طومار ولوستلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_15.mp3', '', 1761754199, 1761754199),
(41964, 'Jeremiah 36:16', 'Jeremiah', 36, 16, 'نو کله چې هغوئ دا کلام واورېدو، نو بيا هغوئ يو بل ته يرې سره کتل او باروک ته يې ووئيل چې، ”مونږ به ضرور بادشاه د دې ټول کلام نه خبر کړُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_16.mp3', '', 1761754199, 1761754199),
(41965, 'Jeremiah 36:17', 'Jeremiah', 36, 17, 'نو بيا هغوئ د باروک نه تپوس وکړو چې، ”تۀ مونږ ته دا ووايه چې دا هر څۀ تا څنګه وليکل؟ آيا يرمياه نبى تا ته وفرمائيل او تا وليکل؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_17.mp3', '', 1761754199, 1761754199),
(41966, 'Jeremiah 36:18', 'Jeremiah', 36, 18, 'باروک ورته جواب ورکړو چې، ”آو، هغۀ دا هر څۀ ما ته وفرمائيل او ما هغه په دې طومار کښې په سياهۍ باندې وليکل.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_18.mp3', '', 1761754199, 1761754199),
(41967, 'Jeremiah 36:19', 'Jeremiah', 36, 19, 'نو آفسرانو باروک ته ووئيل چې، ”تۀ او يرمياه لاړ شئ او خپل ځان پټ کړئ. او هيچا ته مۀ وايئ چې تاسو چرته يئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_19.mp3', '', 1761754199, 1761754199),
(41968, 'Jeremiah 36:20', 'Jeremiah', 36, 20, 'نو بيا آفسرانو هغه طومار د دربار د منشى اليسمع په کوټه کښې کېښودو، نو بيا هغوئ د بادشاه دربار ته لاړل او د دې ټول کلام نه يې بادشاه خبر کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_20.mp3', '', 1761754199, 1761754199),
(41969, 'Jeremiah 36:21', 'Jeremiah', 36, 21, 'نو بادشاه يهودى نومې سړے ورولېږلو چې هغه طومار راوړى، نو يهودى هغه د اليسمع منشى د کوټې نه راوړو او بادشاه او هغه ټولو آفسرانو ته چې ورسره په خوا کښې ولاړ وُو ولوستلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_21.mp3', '', 1761754199, 1761754199),
(41970, 'Jeremiah 36:22', 'Jeremiah', 36, 22, 'نو د کال نهمه مياشت وه، د يخنۍ موسم وو نو بادشاه په شاهى محل کښې د ژمى دپاره په جوړه شوې کوټه کښې نغرى ته ناست وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_22.mp3', '', 1761754199, 1761754199),
(41971, 'Jeremiah 36:23', 'Jeremiah', 36, 23, 'هرکله چې يهودى درې څلور عنوانونه ولوستل، نو بادشاه دا طومار په چاقو وشلولو او هغه يې په نغرى کښې اور ته واچولو، تر دې چې هغه طومار ټول په اور کښې وسوزېدو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_23.mp3', '', 1761754199, 1761754199),
(41972, 'Jeremiah 36:24', 'Jeremiah', 36, 24, 'بادشاه او د هغۀ ټولو خِدمتګارانو چا چې دا کلام واورېدو هغوئ ونۀ يرېدل او نۀ يې د غم نه جامې وشلولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_24.mp3', '', 1761754199, 1761754199),
(41973, 'Jeremiah 36:25', 'Jeremiah', 36, 25, 'کۀ څۀ هم چې الناتن، دلاياه او ګمرياه بادشاه ته مِنتُونه کول چې طومار مۀ سوزوه خو هغۀ د هغوئ خبرې ته غوږ ونۀ نيولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_25.mp3', '', 1761754199, 1761754199),
(41974, 'Jeremiah 36:26', 'Jeremiah', 36, 26, 'نو بيا د دې په ځائ بادشاه يرحمئيل شهزاده او ورسره سراياه د عزرائيل زوئ او شلمياه د عبدائيل زوئ ته حکم وکړو چې باروک منشى او يرمياه نبى ګرفتار کړى. خو مالِک خُدائ هغوئ پټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_26.mp3', '', 1761754199, 1761754199),
(41975, 'Jeremiah 36:27', 'Jeremiah', 36, 27, 'کله چې يهويقيم هغه طومار وسوزولو چې په کښې هغه الفاظ وُو کوم چې باروک ته يرمياه فرمائيلى وُو او هغۀ ليکلى وُو، نو د مالِک خُدائ کلام په يرمياه نازل شو او ورته يې وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_27.mp3', '', 1761754199, 1761754199),
(41976, 'Jeremiah 36:28', 'Jeremiah', 36, 28, '”يو بل طومار راواخله او په هغې کښې هغه هر څۀ وليکه څۀ چې په اول طومار کښې ليکلے شوى وُو کوم چې يهويقيم د يهوداه بادشاه وسوزولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_28.mp3', '', 1761754199, 1761754199),
(41977, 'Jeremiah 36:29', 'Jeremiah', 36, 29, 'نو همدارنګه يهويقيم د يهوداه بادشاه ته ووايه، مالِک خُدائ داسې فرمائى چې، تا دا طومار وسوزولو او يرمياه ته دې وئيل چې، تا ولې په دې کښې دا ليکلى دى چې په يقين سره به د بابل بادشاه راشى او په حقيقت کښې به دا مُلک تباه کړى او انسان او ځناور داوړه به په کښې جارُو کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_29.mp3', '', 1761754199, 1761754199),
(41978, 'Jeremiah 36:30', 'Jeremiah', 36, 30, 'نو په دې وجه مالِک خُدائ د يهويقيم د يهوداه بادشاه په حقله فرمائى چې، د هغۀ په اولاد کښې به څوک هم د داؤد په تخت بادشاهى ونۀ کړى، او د هغۀ لاش به په خوشى مېدان وغورزولے شى چرته چې په ورځ کښې به نمر او په شپه کښې به سختې يخنۍ او پرخې ته پروت وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_30.mp3', '', 1761754199, 1761754199),
(41979, 'Jeremiah 36:31', 'Jeremiah', 36, 31, 'زۀ به هغۀ ته او د هغۀ اولاد او د هغۀ نوکرانو ته د هغوئ د غلطو کارونو په وجه سزا ورکړم، زۀ به په دوئ او په هغه چا باندې چې په يروشلم کښې اوسيږى او د يهوداه په ټولو خلقو به هغه افتونه راولم کوم چې ما د هغوئ خلاف اعلان کړى دى، ځکه چې هغوئ ما ته غوږ ونۀ نيولو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_31.mp3', '', 1761754199, 1761754199),
(41980, 'Jeremiah 36:32', 'Jeremiah', 36, 32, 'بيا يرمياه يو بل تش طومار راواخستلو او باروک ليکوال د نيرياه زوئ له يې ورکړو، نو څنګه به چې يرمياه فرمائيل نو هغه ټول الفاظ يې په کښې دوباره وليکل کوم چې په هغه طومار کښې ليکلے شوى وُو چې يهويقيم د يهوداه بادشاه په اور کښې اچولے او سوزولے وو. او د هغې نه علاوه يې نوره هم په دې موضوع رڼا واچوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah36_verse_32.mp3', '', 1761754199, 1761754199),
(41981, 'Daniel 2:1', 'Daniel', 2, 1, 'د خپلې بادشاهۍ په دوېم کال، نبوکدنضر داسې خوبونه وليدل چې د هغۀ سوچ يې ګډ‌وډ کړو، او هغۀ ته بيا خوب نۀ ورتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_1.mp3', '', 1761754199, 1761754199),
(41982, 'Daniel 2:2', 'Daniel', 2, 2, 'نو بيا بادشاه جادوګر، فالګر، کوډګر او نجوميان راوغوښتل چې هغۀ ته ووائى چې هغۀ څۀ خوب ليدلے دے. هر کله چې هغوئ راغلل او د بادشاه په وړاندې ودرېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_2.mp3', '', 1761754199, 1761754199),
(41983, 'Daniel 2:3', 'Daniel', 2, 3, 'هغۀ دوئ ته ووئيل، ”ما يو خوب ليدلے دے کوم چې زۀ ډېر پرېشانه کړے يم او زۀ غواړم چې په دې پوهه شم چې د دې خوب څۀ مطلب دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_3.mp3', '', 1761754199, 1761754199),
(41984, 'Daniel 2:4', 'Daniel', 2, 4, 'نو بيا نجوميانو هغۀ ته په آرامى ژبه کښې ووئيل چې، ”بادشاه سلامت دې تر ابده ژوندے وى. خپلو خادِمانو ته دې خپل خوب بيان کړه، نو مونږ به د هغې تعبير تاسو ته ووايو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_4.mp3', '', 1761754199, 1761754199),
(41985, 'Daniel 2:5', 'Daniel', 2, 5, 'خو بادشاه نجوميانو ته ووئيل، ”ما دا پخه فېصله کړې ده، کۀ چرې تاسو ما ته دا ونۀ وايئ چې زما خوب څنګه وو او تعبير يې نۀ کړئ، نو زۀ به تاسو ټوټه ټوټه کړم او ستاسو کورونه به د خاورو په ډېرو بدل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_5.mp3', '', 1761754199, 1761754199),
(41986, 'Daniel 2:6', 'Daniel', 2, 6, 'خو کۀ تاسو ما ته زما خوب ووايئ او بيا د هغې تعبير راته ووايئ، نو زۀ به تاسو ته تحفې، انعامونه او لوئ عزت درکړم. اوس تاسو ما ته زما خوب ووايئ او هغه راته تعبير کړئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_6.mp3', '', 1761754199, 1761754199),
(41987, 'Daniel 2:7', 'Daniel', 2, 7, 'نو يو ځل بيا هغوئ هغۀ ته ووئيل، ”بادشاه دې خپلو خادِمانو ته خپل خوب بيان کړى، او مونږ به يې تعبير کړُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_7.mp3', '', 1761754199, 1761754199),
(41988, 'Daniel 2:8', 'Daniel', 2, 8, 'نو بيا بادشاه هغوئ ته په جواب کښې ووئيل، ”زۀ په دې يقين لرم چې تاسو د وخت نه فائده اخلئ، ځکه چې تاسو په دې پوهه شئ چې دا زما پخه فېصله ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_8.mp3', '', 1761754199, 1761754199),
(41989, 'Daniel 2:9', 'Daniel', 2, 9, 'کۀ چرې تاسو ما ته زما خوب ونۀ وايئ، نو بيا تاسو دپاره صرف يوه سزا ده. تاسو دا صلاح کړې ده چې ما ګمراه کړئ او راته دروغ ووايئ او ما دوکه کړئ، او تاسو دا اُميد ساتئ چې زما سوچ به بدل شى. نو بيا تاسو ما ته زما خوب ووايئ، او بيا زۀ به په دې پوهه شم چې تاسو يې ما ته تعبير هم راکولے شئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_9.mp3', '', 1761754199, 1761754199),
(41990, 'Daniel 2:10', 'Daniel', 2, 10, 'نجوميانو بادشاه ته په جواب کښې ووئيل، ”په زمکه داسې هيڅ څوک نشته چې د بادشاه په دې خبره عمل وکړى. تر اوسه پورې داسې نۀ دى شوى چې يو بادشاه د خپل فالګر، جادوګر يا نجومى نه داسې تپوس کړے وى، کۀ هغه بادشاه هر څومره لوئ او طاقتور وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_10.mp3', '', 1761754199, 1761754199),
(41991, 'Daniel 2:11', 'Daniel', 2, 11, 'بادشاه سلامت تاسو چې څۀ غواړئ هغه يو ناممکن کار دے. دا بادشاه ته د هغۀ د معبودانو نه بغېر هيڅ څوک نۀ شى څرګندولے، او هغوئ د انسانانو سره نۀ اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_11.mp3', '', 1761754199, 1761754199),
(41992, 'Daniel 2:12', 'Daniel', 2, 12, 'بادشاه چې کله دا واورېدل نو په دې هغه ډېر زيات په قهر شو او حکم يې وکړو چې د بابل ټول هوښياران او پوهان دې قتل کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_12.mp3', '', 1761754199, 1761754199),
(41993, 'Daniel 2:13', 'Daniel', 2, 13, 'نو بيا د هوښيارانو د قتلولو حکم جارى شو، او د دانيال او د هغۀ ملګرو پسې يې هم کسان ورولېږل چې هغوئ قتل کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_13.mp3', '', 1761754199, 1761754199),
